def read_params_from_args(args):
    """Read parameters from command line arguments.

    Uses INI file format.
    """
    import configparser
    params = configparser.ConfigParser()
    params['args'] = dict(args)
    return params


def write_params_to_args(params):
    """Write parameters to command line arguments.

    Uses INI file format.
    """
    args = {}
    for section in params.sections():
        if section == 'args':
            continue
        for key in params[section]:
            args[key] = params[section][key]
    return args


